@startuml

class User {
  + userId : string
  + name : string
  + address : string
  + birthday : date
}

class BusinessOwner extends User {
  + linkedinAccount : string
}

class HungryCustomer extends User {
  + deliveryAddress : string
}

class Entertainer extends User {
  + stageName : string
  + bio : string
  + pricePer30Minutes : double
}

class PizzaRestaurant {
  + zipCode : string
  + address : string
  + phoneNumber : string
  + website : string
  + openingHours : string
}

class Pizza {
  + name : string
  + crustStructure : string
  + price : double
}

class Order {
  + orderId : string
  + dateTimePlaced : datetime
  + latestDeliveryTime : time
  + numberOfPeople : int
}

class EntertainmentOrder extends Order {
  + entertainmentType : string
  + duration : time
}

class Availability {
  + day : string
}

BusinessOwner "1" *-- "1..*" PizzaRestaurant
PizzaRestaurant "1" -- "*" Pizza
HungryCustomer "1" -- "*" Order
Order "1" -- "1..*" Pizza
EntertainmentOrder "1" -- "1" Entertainer
Entertainer "1" -- "*" Availability
Availability "1" -- "1" PizzaRestaurant

@enduml

